 "content": "def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2]
    # Use the row with the greatest number of markers as the horizontal trunk.
    counts = {}
    for r, c in points:
        counts[r] = counts.get(r, 0) + 1
    trunk = max(counts, key=lambda r: (counts[r], -r))
    trunk_cols = [c for r, c in points if r == trunk]
    for c in range(min(trunk_cols), max(trunk_cols) + 1):
        if out[trunk][c] == 0:
            out[trunk][c] = 3
    for r, c in points:
        step = 1 if trunk > r else -1
        for rr in range(r + step, trunk, step):
            if out[rr][c] == 0:
                out[rr][c] = 3
    return out
